import{_ as t,o as e,c as o,ag as c}from"./chunks/framework.DO6ntPSX.js";const h=JSON.parse('{"title":"配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/configuration.md","filePath":"zh/guide/configuration.md","lastUpdated":1785115728000}'),a={name:"zh/guide/configuration.md"};function r(i,d,_,n,l,E){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h1><p>复制 <code>.env.example</code> 作为起点。主要设置如下：</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>API_KEY</code></td><td>—</td><td>OpenAI 兼容 API Key</td></tr><tr><td><code>BASE_URL</code></td><td><code>https://api.openai.com/v1</code></td><td>LLM 端点；远程端点必须使用 HTTPS</td></tr><tr><td><code>LLM_MODEL</code></td><td><code>deepseek-chat</code></td><td>聊天和查询拆解模型</td></tr><tr><td><code>LLM_TEMPERATURE</code></td><td><code>0.2</code></td><td>生成温度</td></tr><tr><td><code>LLM_TOP_K_MIN</code></td><td><code>12</code></td><td>标准检索的最小检索 chunk 数</td></tr><tr><td><code>LLM_TOP_K_MAX</code></td><td><code>70</code></td><td>标准检索的最大检索 chunk 数</td></tr><tr><td><code>ALPHA</code></td><td><code>0.7</code></td><td>Graph RAG 语义/图融合权重</td></tr><tr><td><code>RAG_WATCH_DIR</code></td><td>—</td><td>TUI 监听的目录</td></tr><tr><td><code>EMBEDDING_MODEL_PATH</code></td><td>—</td><td>本地 Embedding 模型路径；优先使用</td></tr><tr><td><code>EMBEDDING_MODEL_NAME</code></td><td><code>all-MiniLM-L6-v2</code></td><td>用于本地/ModelScope 加载的 Embedding 模型 ID</td></tr><tr><td><code>MNEME_DOCUMENT_ROOT</code></td><td>—</td><td>允许索引文件的可选根目录</td></tr><tr><td><code>MNEME_MAX_DOCUMENT_BYTES</code></td><td><code>52428800</code></td><td>最大文档大小，50 MiB</td></tr><tr><td><code>MNEME_MAX_PDF_PAGES</code></td><td><code>2000</code></td><td>单个 PDF 接受的最大页数</td></tr><tr><td><code>MNEME_MAX_REMOTE_CONTEXT_CHARS</code></td><td><code>60000</code></td><td>发送到 LLM 端点的最大检索上下文</td></tr><tr><td><code>MNEME_ALLOW_INSECURE_HTTP</code></td><td>未设置</td><td>显式允许非本地 HTTP 端点；仅用于受控开发</td></tr></tbody></table><h2 id="embedding-模型加载" tabindex="-1">Embedding 模型加载 <a class="header-anchor" href="#embedding-模型加载" aria-label="Permalink to &quot;Embedding 模型加载&quot;">​</a></h2><p>Embedding 模型首先从配置的本地路径或缓存加载。如果不可用，Mneme 使用配置的模型 ID 进行 ModelScope 回退；默认为 <code>all-MiniLM-L6-v2</code>。</p><h2 id="端点安全" tabindex="-1">端点安全 <a class="header-anchor" href="#端点安全" aria-label="Permalink to &quot;端点安全&quot;">​</a></h2><p>对于非本地端点，默认要求 HTTPS。纯 HTTP 仅允许用于回环地址，如 <code>localhost</code>、<code>127.0.0.1</code> 和 <code>::1</code>。非本地 HTTP 端点需要显式的 <code>MNEME_ALLOW_INSECURE_HTTP=1</code> 覆盖。</p><h2 id="文档安全措施" tabindex="-1">文档安全措施 <a class="header-anchor" href="#文档安全措施" aria-label="Permalink to &quot;文档安全措施&quot;">​</a></h2><ul><li>文档大小、PDF 页数和可选的允许文档根目录可以受限</li><li><code>.env</code> 被明确拒绝为可索引文档</li><li>检索到的文本被放入显式的不可信文档边界中，以抵抗提示注入</li></ul>',9)])])}const T=t(a,[["render",r]]);export{h as __pageData,T as default};
